begin;
do $$
declare
  v_site_id uuid;
  v_page_id uuid;
  v_document jsonb;
begin
  select id into v_site_id from website.sites where site_key='marktone-main' limit 1;
  select id into v_page_id from website.pages where site_id=v_site_id and is_home and status<>'archived' limit 1;
  if v_page_id is null then raise exception 'marktone_home_page_not_found'; end if;

  select content into v_document from website.pages where id=v_page_id for update;
  v_document:=jsonb_set(
    coalesce(v_document,'{}'::jsonb),
    '{blocks}',
    coalesce(v_document->'blocks','[]'::jsonb)||$blocks$[{"id":"row-solutions","type":"columns","props":{"anchor":"","row":true,"layoutKey":"1-1-1-1","gap":16,"fullWidth":false,"minHeight":0,"verticalAlign":"stretch","items":[{"id":"col-solution-1","width":"1fr","modules":[{"id":"solution-1","type":"linkBlock","props":{"anchor":"","eyebrow":"01","icon":"↗","title":"التسويق والنمو","body":"اربط الحملات بصفحات الهبوط ومصادر العملاء واعرف ما الذي يصنع تسجيلات فعلية.","href":"#platform"},"style":{"variant":"light","align":"right","paddingY":0,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"fade-up","animationDelay":80,"cssClass":"mt-solution-growth"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"col-solution-2","width":"1fr","modules":[{"id":"solution-2","type":"linkBlock","props":{"anchor":"","eyebrow":"02","icon":"◎","title":"المبيعات والعملاء","body":"وزّع العملاء، نظّم المتابعات، راقب خط المبيعات وارفع التحويل دون فقد أي فرصة.","href":"#platform"},"style":{"variant":"light","align":"right","paddingY":0,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"fade-up","animationDelay":160,"cssClass":"mt-solution-sales"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"col-solution-3","width":"1fr","modules":[{"id":"solution-3","type":"linkBlock","props":{"anchor":"","eyebrow":"03","icon":"▦","title":"التشغيل والقبول","b