":[{"id":"heading-command","type":"fancyHeading","props":{"anchor":"","eyebrow":"من لوحة واحدة","title":"شاهد ما يحدث الآن، واعرف ما يجب أن يحدث بعد ذلك","body":"لا تجمع تقارير متأخرة من أدوات متعددة. ماركتون توحّد رحلة العميل وأداء الفريق وتشغيل البرامج لتمنح الإدارة صورة عملية قابلة للتصرف.","accent":"قرار أسرع. متابعة أدق.","level":"h2"},"style":{"variant":"dark","align":"right","paddingY":12,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"fade-up","animationDelay":0,"cssClass":"mt-command-title"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"buttons-command","type":"buttons","props":{"anchor":"","primaryLabel":"شاهد المنصة عمليًا","primaryHref":"/free-trial","secondaryLabel":"تعرّف على الوحدات","secondaryHref":"#platform"},"style":{"variant":"dark","align":"right","paddingY":8,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-command-actions"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":6,"gap":12,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"center"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"col-command-visual","width":"1fr","modules":[{"id":"html-command","type":"html","props":{"anchor":"","content":"<div class=\"mt-command\"><header><span>مركز القرار</span><b>كل رحلة عميل واضحة من المصدر حتى التسجيل</b></header><div class=\"mt-command-flow\"><article><i>01</i><div><b>مصدر العميل</b><span>حملة، متجر، موقع أو إحالة</span></div><em>متصل</em></article><article><i>02</i><div><b>فريق المبيعات</b><span>توزيع، متابعة ومواعيد تلقائية</span></div><em>منظّم</em></article><article><i>03</i><div><b>التسجيل والقبول</b><span>تحويل سلس بعد الدفع</span></div><em>مكتمل</em></article><article><i>04</i><div><b>القرار الإداري</b><span>مؤشرات لحظية وأداء قابل للقياس</span></div><em>واضح</em></article></div><footer><span>التسويق</span><span>CRM</span><span>المهام</span><span>الدورات</span><span>القبول</span><span>التحليلات</span></footer></div>"},"style":{"variant":"dark","align":"right","paddingY":0,"maxWidth":"full","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"slide-left","animationDelay":0,"cssClass":"mt-command-visual"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"center"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]},"style":{"variant":"dark","align":"right","paddingY":70,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-command-row"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]$blocks$::jsonb,
    true
  );
  v_document:=private_app.website_builder_validate_document(v_document);

  update website.pages set content=v_document,updated_at=now() where id=v_page_id;
  update website.content_documents
  set draft_document=v_document,published_document=v_document,
      draft_updated_at=now(),published_at=now(),updated_at=now()
  where site_id=v_site_id and entity_type='page' and entity_id=v_page_id;
end
$$;
commit;
